// ============================================================
//  Ballpit.jsx — Improved to match React Bits style
// ============================================================

import { useEffect, useRef } from 'react';
import * as THREE from 'three';

const Ballpit = ({
  count = 80,
  gravity = 0.18,
  friction = 0.975,
  wallBounce = 0.85,
}) => {
  const canvasRef = useRef(null);
  const rafRef = useRef(null);

  useEffect(() => {
    const canvas = canvasRef.current;
    if (!canvas) return;

    const scene = new THREE.Scene();
    const camera = new THREE.PerspectiveCamera(45, 1, 0.1, 100);
    camera.position.set(0, 2, 28);

    const renderer = new THREE.WebGLRenderer({
      canvas,
      antialias: true,
      alpha: true,
    });
    renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
    renderer.outputColorSpace = THREE.SRGBColorSpace;

    // Lights
    scene.add(new THREE.AmbientLight(0xffffff, 0.8));
    const pointLight = new THREE.PointLight(0xc4b5fd, 3, 100);
    pointLight.position.set(5, 10, 15);
    scene.add(pointLight);

    // Material (glossy purple/white look)
    const material = new THREE.MeshPhysicalMaterial({
      color: 0x8b5cf6,
      metalness: 0.1,
      roughness: 0.1,
      clearcoat: 1.0,
      clearcoatRoughness: 0.05,
      envMapIntensity: 1.2,
    });

    const geometry = new THREE.SphereGeometry(1, 48, 48);
    const balls = new THREE.InstancedMesh(geometry, material, count);
    const dummy = new THREE.Object3D();
    scene.add(balls);

    // Physics arrays
    const positions = new Float32Array(count * 3);
    const velocities = new Float32Array(count * 3);
    const sizes = new Float32Array(count);

    // Initialize balls (mostly at bottom)
    for (let i = 0; i < count; i++) {
      const idx = i * 3;
      positions[idx]     = (Math.random() - 0.5) * 22;
      positions[idx + 1] = -8 + Math.random() * 12;        // Start lower
      positions[idx + 2] = (Math.random() - 0.5) * 8;

      velocities[idx]     = (Math.random() - 0.5) * 3;
      velocities[idx + 1] = Math.random() * -2;
      velocities[idx + 2] = (Math.random() - 0.5) * 2;

      sizes[i] = 0.7 + Math.random() * 1.1;
    }

    let lastTime = 0;

    const animate = (time = 0) => {
      rafRef.current = requestAnimationFrame(animate);
      const delta = Math.min((time - lastTime) / 1000, 0.1);
      lastTime = time;

      for (let i = 0; i < count; i++) {
        const idx = i * 3;

        velocities[idx + 1] -= gravity * delta * 60;   // Stronger gravity

        velocities[idx] *= friction;
        velocities[idx + 1] *= friction;
        velocities[idx + 2] *= friction;

        positions[idx]     += velocities[idx] * delta * 60;
        positions[idx + 1] += velocities[idx + 1] * delta * 60;
        positions[idx + 2] += velocities[idx + 2] * delta * 60;

        const r = sizes[i];

        // Bottom floor
        if (positions[idx + 1] - r < -9.5) {
          positions[idx + 1] = -9.5 + r;
          velocities[idx + 1] *= -wallBounce * 0.85;   // Less bouncy on floor
        }

        // Side walls
        if (Math.abs(positions[idx]) + r > 13) {
          positions[idx] = Math.sign(positions[idx]) * (13 - r);
          velocities[idx] *= -wallBounce;
        }
        if (Math.abs(positions[idx + 2]) + r > 8) {
          positions[idx + 2] = Math.sign(positions[idx + 2]) * (8 - r);
          velocities[idx + 2] *= -wallBounce;
        }
      }

      // Update visual balls
      for (let i = 0; i < count; i++) {
        const idx = i * 3;
        dummy.position.set(positions[idx], positions[idx + 1], positions[idx + 2]);
        dummy.scale.setScalar(sizes[i]);
        dummy.updateMatrix();
        balls.setMatrixAt(i, dummy.matrix);
      }

      balls.instanceMatrix.needsUpdate = true;
      renderer.render(scene, camera);
    };

    const handleResize = () => {
      const parent = canvas.parentElement;
      camera.aspect = parent.offsetWidth / parent.offsetHeight;
      camera.updateProjectionMatrix();
      renderer.setSize(parent.offsetWidth, parent.offsetHeight);
    };

    window.addEventListener('resize', handleResize);
    handleResize();
    animate();

    return () => {
      cancelAnimationFrame(rafRef.current);
      window.removeEventListener('resize', handleResize);
      renderer.dispose();
    };
  }, [count, gravity, friction, wallBounce]);

  return (
    <canvas
      ref={canvasRef}
      className="hero__ballpit"
      style={{ width: '100%', height: '100%' }}
    />
  );
};

export default Ballpit;
